cd "$GITHUB_WORKSPACE" && git fetch origin main --quiet && python3 - <<'PY'
import subprocess,glob
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits={}
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H',f'origin/friend/{b}'],text=True)
    for sha in out.split():
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' not in msg: continue
        ep=None
        for l in msg.splitlines():
            if l.startswith('Episode:'): ep=l.split(':',1)[1].strip()
        commits[sha]=(b,ep)
# sources from origin/main tree
sources=set()
# list episode files in origin/main
out=subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True)
for f in out.split():
    if not (f.startswith('S') and '/E' in f and f.endswith('.md')): continue
    content=subprocess.check_output(['git','show',f'origin/main:{f}'],text=True)
    for l in content.splitlines():
        if l.startswith('Source: '):
            sources.add(l.strip().split('@')[-1].strip())
missing=[(sha,b,ep) for sha,(b,ep) in commits.items() if sha not in sources]
print('total commits',len(commits),'sources',len(sources),'missing',len(missing))
for m in sorted(missing):
    print(m)
